CREATE TABLE public.pricepilot_market_comparables (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source text NOT NULL,
  source_listing_id text,
  source_url text,
  source_title text NOT NULL,
  captured_at timestamptz NOT NULL DEFAULT now(),
  observed_status text NOT NULL DEFAULT 'unknown' CHECK (observed_status IN ('sold', 'pending', 'active', 'unknown')),
  asset_category text NOT NULL DEFAULT 'other' CHECK (asset_category IN ('food_truck', 'food_trailer', 'food_cart', 'mobile_bar', 'vendor_space', 'generic_trailer', 'vehicle_only', 'other')),
  valuation_mode text NOT NULL DEFAULT 'sale' CHECK (valuation_mode IN ('sale', 'rental')),
  city text,
  state text,
  year integer,
  make text,
  model text,
  length_ft numeric,
  displayed_price numeric,
  previous_displayed_price numeric,
  claimed_sale_price numeric,
  verified_transaction_price numeric,
  transaction_price_verified boolean NOT NULL DEFAULT false,
  raw_text text,
  extraction_confidence numeric,
  evidence_confidence numeric,
  usable_for_valuation boolean NOT NULL DEFAULT true,
  quality_flags jsonb NOT NULL DEFAULT '[]'::jsonb,
  normalized_features jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT ALL ON public.pricepilot_market_comparables TO service_role;

ALTER TABLE public.pricepilot_market_comparables ENABLE ROW LEVEL SECURITY;

CREATE INDEX idx_pricepilot_comps_lookup ON public.pricepilot_market_comparables (valuation_mode, asset_category, state, observed_status) WHERE usable_for_valuation;

CREATE INDEX idx_pricepilot_comps_price ON public.pricepilot_market_comparables (displayed_price) WHERE usable_for_valuation AND displayed_price IS NOT NULL;

CREATE TRIGGER trg_pricepilot_comps_updated_at BEFORE UPDATE ON public.pricepilot_market_comparables FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

